import unittest
from src.search import search


class SearchTests(unittest.TestCase):
    def test_chinese_keyword(self):
        self.assertEqual(search(['欢迎页面', '项目规划'], '欢迎'), ['欢迎页面'])

    def test_english_keyword(self):
        self.assertEqual(search(['Hello World', '其他页面'], 'hello'), ['Hello World'])

    def test_empty_and_missing_keyword(self):
        self.assertEqual(search(['欢迎页面'], '不存在'), [])
        self.assertEqual(search(['欢迎页面'], '  '), [])
